<?php
declare(strict_types=1);namespace Vendi\Inventory;use PDO;use RuntimeException;
final class InventoryCountService{public function __construct(private PDO $db){}
 public function post(int$b,int$branch,int$u,array$items,?string$notes=null):int{if(!$items)throw new RuntimeException('Agrega productos al conteo.');$own=!$this->db->inTransaction();if($own)$this->db->beginTransaction();try{$this->db->prepare("INSERT INTO inventory_counts(business_id,branch_id,user_id,status,notes,created_at) VALUES(?,?,?,'draft',?,NOW())")->execute([$b,$branch,$u,$notes]);$cid=(int)$this->db->lastInsertId();foreach($items as$x){$pid=(int)$x['product_id'];$vid=!empty($x['variant_id'])?(int)$x['variant_id']:null;$s=$this->db->prepare("SELECT qty FROM inventory WHERE business_id=? AND branch_id=? AND product_id=? FOR UPDATE");$s->execute([$b,$branch,$pid]);$sys=(float)($s->fetchColumn()?:0);$count=(float)$x['counted_qty'];$diff=$count-$sys;$this->db->prepare("INSERT INTO inventory_count_items(count_id,product_id,variant_id,system_qty,counted_qty,difference_qty,reason) VALUES(?,?,?,?,?,?,?)")->execute([$cid,$pid,$vid,$sys,$count,$diff,$x['reason']??null]);if(abs($diff)>.000001){$this->db->prepare("INSERT INTO inventory(business_id,branch_id,product_id,qty) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE qty=VALUES(qty)")->execute([$b,$branch,$pid,$count]);$this->db->prepare("INSERT INTO stock_movements(business_id,branch_id,product_id,user_id,variant_id,type,qty,reference_type,reference_id) VALUES(?,?,?,?,?,'adjustment',?,'inventory_count',?)")->execute([$b,$branch,$pid,$u,$vid,$diff,$cid]);}}$this->db->prepare("UPDATE inventory_counts SET status='posted',posted_at=NOW() WHERE id=?")->execute([$cid]);if($own)$this->db->commit();return$cid;}catch(\Throwable$e){if($own&&$this->db->inTransaction())$this->db->rollBack();throw$e;}}
 public function lowStock(int$b,int$branch):array{$q=$this->db->prepare("SELECT p.id,p.name,p.sku,COALESCE(i.qty,0) quantity,p.min_stock,p.max_stock FROM products p LEFT JOIN inventory i ON i.product_id=p.id AND i.branch_id=? AND i.business_id=? WHERE p.business_id=? AND p.min_stock IS NOT NULL AND COALESCE(i.qty,0)<=p.min_stock ORDER BY (p.min_stock-COALESCE(i.qty,0)) DESC,p.name");$q->execute([$branch,$b,$b]);return$q->fetchAll();}
}